package dev.shadw.asgard.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Draugr Lord with its own model and texture. Generated by shadw-mod mob. */
public class DraugrLordRenderer extends MobRenderer<DraugrLord, DraugrLordModel.State, DraugrLordModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("asgard", "textures/entity/draugr_lord.png");

	public DraugrLordRenderer(EntityRendererProvider.Context context) {
		super(context, new DraugrLordModel(context.bakeLayer(DraugrLordModel.LAYER)), 0.55F);
	}

	@Override
	public DraugrLordModel.State createRenderState() {
		return new DraugrLordModel.State();
	}

	@Override
	public void extractRenderState(DraugrLord entity, DraugrLordModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(DraugrLordModel.State state) {
		return TEXTURE;
	}
}
